If you have files of your own that you’d like to process, add them to the img folder.

You can also add metadata about the images in a manifest.json file in the img folder.

%%writefile manifest.json

{
  "@context":"http://iiif.io/api/presentation/2/context.json",
  "@id":"<your Id here>",
  "@type":"sc:Manifest",
  "label":"<Your label here>",
  "description":"<Your description here>",
  "attribution":"Creative commons attribution non-commercial licence",
  "license":"https://creativecommons.org/licenses/by-nc/4.0/",
  "metadata":[
    {
      "label":"Identifier",
      "value":"EAP1477/1/1/1"
    },
    {
      "label":"Title",
      "value":"Caja 1"
    },
    {
      "label":"Place",
      "value":"Choc\u00f3, Colombia, Colombia, South America, Istmina, Choc\u00f3, Colombia"
    },
    {
      "label":"Link to catalogue record",
      "value":"<a href=\"https://eap.bl.uk/archive-file/EAP1477-1-1-1\">View the catalogue record</a>"
    },
    {
      "label":"Citation",
      "value":"Caja 1, British Library, EAP1477/1/1/1, https://eap.bl.uk/archive-file/EAP1477-1-1-1"
    },
    {
      "label":"Digitised by",
      "value":"University of Pennsylvania"
    },
    {
      "label":"Digitisation funded by",
      "value":"Endangered Archives Programme supported by Arcadia"
    },
    {
      "label":"Language",
      "value":"Spanish"
    },
    {
      "label":"Scripts",
      "value":"Latin"
    }
  ]
}
